//! `args::parse` against the Python engine's real argparse parser (fixture generated by
//! `tests/fixtures/gen_argparse_golden.py` with CPython 3.11.18, COLUMNS=80): exit code, stdout, stderr, and
//! every parsed value.

use std::ffi::OsString;

use se_cli::args::{Args, Command, Parsed, parse};
use se_core::json::{self, Map, Value};
use se_core::paths::py_path_str;

fn s(v: &str) -> Value {
    Value::from(v)
}

fn p(path: &std::path::Path) -> Value {
    Value::Object(Map::new().with("path", py_path_str(path)))
}

fn opt(v: &Option<String>) -> Value {
    v.as_deref().map(Value::from).unwrap_or(Value::Null)
}

/// The namespace Python would hold (`vars(args)` minus `handler`) as JSON.
fn namespace(args: &Args) -> Map {
    let mut m = Map::new();
    m.insert("lang", opt(&args.lang));
    m.insert("offline", Value::from(args.offline));
    m.insert("sub_lang", opt(&args.sub_lang));
    let command = match &args.command {
        Command::ExtractAudio { video, out_dir, json } => {
            m.insert("video", p(video));
            m.insert("out_dir", p(out_dir));
            m.insert("json", Value::from(*json));
            "extract-audio"
        }
        Command::Preview { video, output, json } => {
            m.insert("video", p(video));
            m.insert("output", p(output));
            m.insert("json", Value::from(*json));
            "preview"
        }
        Command::Transcribe { video, out_dir, language, model, formats, max_chars, max_duration, diarize, speakers, json } => {
            m.insert("video", p(video));
            m.insert("out_dir", p(out_dir));
            m.insert("language", opt(language));
            m.insert("model", s(model));
            m.insert("format", Value::Array(formats.iter().map(|f| s(f)).collect()));
            m.insert("max_chars", Value::from(*max_chars));
            m.insert("max_duration", Value::from(*max_duration));
            m.insert("diarize", Value::from(*diarize));
            m.insert("speakers", speakers.map(Value::from).unwrap_or(Value::Null));
            m.insert("json", Value::from(*json));
            "transcribe"
        }
        Command::Translate { to, source, model, json } => {
            m.insert("to", s(to));
            m.insert("source", opt(source));
            m.insert("model", s(model));
            m.insert("json", Value::from(*json));
            "translate"
        }
        Command::Render { format, out } => {
            m.insert("format", s(format));
            m.insert("out", out.as_deref().map(p).unwrap_or(Value::Null));
            "render"
        }
        Command::Models { json } => {
            m.insert("json", Value::from(*json));
            "models"
        }
        Command::DeleteModel { id, json } => {
            m.insert("id", s(id));
            m.insert("json", Value::from(*json));
            "delete-model"
        }
    };
    m.insert("command", s(command));
    m
}

fn sorted(m: &Map) -> String {
    json::dumps_with(
        &Value::Object(m.clone()),
        &json::DumpOptions { sort_keys: true, ..json::DumpOptions::default() },
    )
}

#[test]
fn test_parser_matches_python_argparse() {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/argparse_golden.json")).unwrap();
    let cases = json::parse(&text).unwrap();
    let mut failures = Vec::new();
    for case in cases.as_array().unwrap() {
        let argv: Vec<String> =
            case.get("argv").unwrap().as_array().unwrap().iter().map(|a| a.as_str().unwrap().to_string()).collect();
        let os: Vec<OsString> = argv.iter().map(OsString::from).collect();
        let got = parse(&os);
        let ok = match (&got, case.get("code").unwrap()) {
            (Parsed::Exit { code, stdout, stderr }, Value::Int(want)) => {
                i64::from(*code) == *want
                    && stdout == case.get("stdout").unwrap().as_str().unwrap()
                    && stderr == case.get("stderr").unwrap().as_str().unwrap()
            }
            (Parsed::Run(args), Value::Null) => {
                sorted(&namespace(args)) == sorted(case.get("ns").unwrap().as_object().unwrap())
            }
            _ => false,
        };
        if !ok {
            failures.push(format!("{argv:?}\n  want: {}\n  got:  {got:?}", json::dumps(case, false)));
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}
